1	// Command payflow is the 链上支付与结算编排平台 entry point.
2	package main
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11	
12		"github.com/gzhysuiioo/payflow-settlement/payflow"
13	)
14	
15	func main() {
16		os.Exit(runCLI(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
17	}
18	
19	const versionString = "payflow 0.2.0"
20	
21	func runCLI(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
22		if len(args) == 0 {
23			return runDemo(stdout)
24		}
25		switch args[0] {
26		case "demo":
27			return runDemo(stdout)
28		case "version":
29			fmt.Fprintln(stdout, versionString)
30			return 0
31		case "help", "-h", "--help":
32			usage(stdout)
33			return 0
34		case "init":
35			return cmdInit(args[1:], stdin, stdout, stderr)
36		case "submit":
37			return cmdSubmit(args[1:], stdin, stdout, stderr)
38		case "refund":
39			return cmdRefund(args[1:], stdin, stdout, stderr)
40		case "query":
41			return cmdQuery(args[1:], stdout, stderr)
42		case "reconcile":
43			return cmdReconcile(args[1:], stdin, stdout, stderr)
44		default:
45			fmt.Fprintf(stderr, "unknown command %q\n", args[0])
46			usage(stderr)
47			return 2
48		}
49	}
50	
51	func usage(w io.Writer) {
52		fmt.Fprintln(w, "usage: payflow <command> [flags]")
53		fmt.Fprintln(w, "")
54		fmt.Fprintln(w, "commands:")
55		fmt.Fprintln(w, "  init       initialize a ledger with starting balances")
56		fmt.Fprintln(w, "  submit     submit a JSON payment batch against a ledger")
57		fmt.Fprintln(w, "  refund     submit a JSON full-refund batch against a ledger")
58		fmt.Fprintln(w, "  query      print balances, settlement and refund records of a ledger")
59		fmt.Fprintln(w, "  reconcile  reconcile an ordered JSON flow against a ledger")
60		fmt.Fprintln(w, "  demo       run the in-memory settlement demo")
61		fmt.Fprintln(w, "  version    print version")
62		fmt.Fprintln(w, "  help       show this help")
63		fmt.Fprintln(w, "")
64		fmt.Fprintln(w, "ledger flags (init/submit/refund/query/reconcile):")
65		fmt.Fprintln(w, "  -l, --ledger <path>   ledger file path (required)")
66		fmt.Fprintln(w, "  -f, --file <path>     JSON input file (init/submit/refund/reconcile; default: stdin)")
67		fmt.Fprintln(w, "")
68		fmt.Fprintln(w, "submit flags:")
69		fmt.Fprintln(w, "  --dry-run             preview settlement results without writing the ledger")
70		fmt.Fprintln(w, "")
71		fmt.Fprintln(w, "reconcile range flags (seq bounds, after < seq <= through; default: full history):")
72		fmt.Fprintln(w, "  --payment-after <n>    payment seq lower bound (exclusive)")
73		fmt.Fprintln(w, "  --payment-through <n>  payment seq upper bound (inclusive)")
74		fmt.Fprintln(w, "  --refund-after <n>     refund seq lower bound (exclusive)")
75		fmt.Fprintln(w, "  --refund-through <n>   refund seq upper bound (inclusive)")
76	}
77	
78	// initRequest 是 init 的输入：{"balances":[...]}。
79	type initRequest struct {
80		Balances []payflow.BalanceInit `json:"balances"`
81	}
82	
83	type errorEnvelope struct {
84		Error struct {
85			Kind    string `json:"kind"`
86			Message string `json:"message"`
87		} `json:"error"`
88	}
89	
90	func failEnvelope(stderr io.Writer, kind, message string) int {
91		env := errorEnvelope{}
92		env.Error.Kind = kind
93		env.Error.Message = message
94		writeJSON(stderr, env)
95		return 1
96	}
97	
98	func failWithError(stderr io.Writer, err error) int {
99		return failEnvelope(stderr, payflow.KindOf(err), err.Error())
100	}
101	
102	func writeJSON(w io.Writer, v any) {
103		data, err := json.MarshalIndent(v, "", "  ")
104		if err != nil {
105			fmt.Fprintf(w, `{"error":{"kind":"storage_error","message":%q}}`+"\n", err.Error())
106			return
107		}
108		w.Write(data)
109		w.Write([]byte("\n"))
110	}
111	
112	// ledgerFlagSet 构造 -l/--ledger、-f/--file 标志。
113	func ledgerFlagSet(name string) (*flag.FlagSet, *string, *string) {
114		fs := flag.NewFlagSet(name, flag.ContinueOnError)
115		fs.SetOutput(io.Discard)
116		var ledgerPath, inputFile string
117		fs.StringVar(&ledgerPath, "ledger", "", "ledger file path")
118		fs.StringVar(&ledgerPath, "l", "", "ledger file path (shorthand)")
119		fs.StringVar(&inputFile, "file", "", "JSON input file (default stdin)")
120		fs.StringVar(&inputFile, "f", "", "JSON input file (shorthand)")
121		return fs, &ledgerPath, &inputFile
122	}
123	
124	func readInput(path string, stdin io.Reader) ([]byte, error) {
125		if path == "" {
126			return io.ReadAll(stdin)
127		}
128		return os.ReadFile(path)
129	}
130	
131	func cmdInit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
132		fs, ledgerPath, inputFile := ledgerFlagSet("init")
133		if err := fs.Parse(args); err != nil {
134			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
135		}
136		if *ledgerPath == "" {
137			return failEnvelope(stderr, payflow.ErrInvalid, "init requires --ledger <path>")
138		}
139		raw, err := readInput(*inputFile, stdin)
140		if err != nil {
141			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
142		}
143		var req initRequest
144		dec := json.NewDecoder(bytes.NewReader(raw))
145		if err := dec.Decode(&req); err != nil {
146			return failEnvelope(stderr, payflow.ErrInvalid, "parse init JSON: "+err.Error())
147		}
148		if err := requireEOF(dec, "init"); err != nil {
149			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
150		}
151		if err := payflow.CreateLedger(*ledgerPath, req.Balances); err != nil {
152			return failWithError(stderr, err)
153		}
154		writeJSON(stdout, map[string]any{
155			"status":   "initialized",
156			"ledger":   *ledgerPath,
157			"accounts": len(req.Balances),
158		})
159		return 0
160	}
161	
162	func cmdSubmit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
163		fs, ledgerPath, inputFile := ledgerFlagSet("submit")
164		var dryRun bool
165		fs.BoolVar(&dryRun, "dry-run", false, "preview settlement results without writing the ledger")
166		if err := fs.Parse(args); err != nil {
167			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
168		}
169		if *ledgerPath == "" {
170			return failEnvelope(stderr, payflow.ErrInvalid, "submit requires --ledger <path>")
171		}
172		raw, err := readInput(*inputFile, stdin)
173		if err != nil {
174			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
175		}
176		var batch payflow.FeeBatch
177		dec := json.NewDecoder(bytes.NewReader(raw))
178		if err := dec.Decode(&batch); err != nil {
179			return failEnvelope(stderr, payflow.ErrInvalid, "parse batch JSON: "+err.Error())
180		}
181		if err := requireEOF(dec, "submit"); err != nil {
182			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
183		}
184	
185		l, err := payflow.Open(*ledgerPath)
186		if err != nil {
187			return failWithError(stderr, err)
188		}
189		defer l.Close()
190	
191		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
192		// --dry-run 只预测业务结果：不写入账本，输出带 dry_run:true 标记。
193		if dryRun {
194			result, err := l.Preview(batch)
195			if err != nil {
196				return failWithError(stderr, err)
197			}
198			writeJSON(stdout, result)
199			return 0
200		}
201		result, err := l.Submit(batch)
202		if err != nil {
203			return failWithError(stderr, err)
204		}
205		writeJSON(stdout, result)
206		return 0
207	}
208	
209	func cmdRefund(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
210		fs, ledgerPath, inputFile := ledgerFlagSet("refund")
211		if err := fs.Parse(args); err != nil {
212			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
213		}
214		if *ledgerPath == "" {
215			return failEnvelope(stderr, payflow.ErrInvalid, "refund requires --ledger <path>")
216		}
217		raw, err := readInput(*inputFile, stdin)
218		if err != nil {
219			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
220		}
221		var batch payflow.RefundBatch
222		dec := json.NewDecoder(bytes.NewReader(raw))
223		if err := dec.Decode(&batch); err != nil {
224			return failEnvelope(stderr, payflow.ErrInvalid, "parse refund batch JSON: "+err.Error())
225		}
226		if err := requireEOF(dec, "refund"); err != nil {
227			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
228		}
229	
230		l, err := payflow.Open(*ledgerPath)
231		if err != nil {
232			return failWithError(stderr, err)
233		}
234		defer l.Close()
235	
236		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
237		result, err := l.Refund(batch)
238		if err != nil {
239			return failWithError(stderr, err)
240		}
241		writeJSON(stdout, result)
242		return 0
243	}
244	
245	func cmdQuery(args []string, stdout, stderr io.Writer) int {
246		fs, ledgerPath, _ := ledgerFlagSet("query")
247		if err := fs.Parse(args); err != nil {
248			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
249		}
250		if *ledgerPath == "" {
251			return failEnvelope(stderr, payflow.ErrInvalid, "query requires --ledger <path>")
252		}
253		l, err := payflow.Open(*ledgerPath)
254		if err != nil {
255			return failWithError(stderr, err)
256		}
257		defer l.Close()
258		snap, err := l.Query()
259		if err != nil {
260			return failWithError(stderr, err)
261		}
262		writeJSON(stdout, snap)
263		return 0
264	}
265	
266	func cmdReconcile(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
267		fs, ledgerPath, inputFile := ledgerFlagSet("reconcile")
268		// 序号边界：after 排除下界、through 包含上界（after < seq <= through）。
269		// 用指针区分“未提供”与显式给出的 0：未提供时由库取缺省值（下界 0、
270		// 上界为该类记录的最大成功序号）。
271		var paymentAfter, paymentThrough, refundAfter, refundThrough int64
272		fs.Int64Var(&paymentAfter, "payment-after", 0, "payment seq lower bound (exclusive)")
273		fs.Int64Var(&paymentThrough, "payment-through", 0, "payment seq upper bound (inclusive)")
274		fs.Int64Var(&refundAfter, "refund-after", 0, "refund seq lower bound (exclusive)")
275		fs.Int64Var(&refundThrough, "refund-through", 0, "refund seq upper bound (inclusive)")
276		if err := fs.Parse(args); err != nil {
277			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
278		}
279		if *ledgerPath == "" {
280			return failEnvelope(stderr, payflow.ErrInvalid, "reconcile requires --ledger <path>")
281		}
282		raw, err := readInput(*inputFile, stdin)
283		if err != nil {
284			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
285		}
286		// 先严格解析全部输入：任一条目不合法则整次拒绝，退出码 1，不输出部分报告。
287		entries, err := payflow.ParseReconcileRequest(raw)
288		if err != nil {
289			return failWithError(stderr, err)
290		}
291	
292		bounds := payflow.ReconcileBounds{}
293		fs.Visit(func(f *flag.Flag) {
294			switch f.Name {
295			case "payment-after":
296				v := paymentAfter
297				bounds.PaymentAfter = &v
298			case "payment-through":
299				v := paymentThrough
300				bounds.PaymentThrough = &v
301			case "refund-after":
302				v := refundAfter
303				bounds.RefundAfter = &v
304			case "refund-through":
305				v := refundThrough
306				bounds.RefundThrough = &v
307			}
308		})
309	
310		l, err := payflow.Open(*ledgerPath)
311		if err != nil {
312			return failWithError(stderr, err)
313		}
314		defer l.Close()
315	
316		// 对账只读：不改余额、历史或账本文件。边界非法同样整次拒绝、不输出部分
317		// 报告；输入有差异仍是正常结果，退出码 0。
318		report, err := l.ReconcileFlowRanged(entries, bounds)
319		if err != nil {
320			return failWithError(stderr, err)
321		}
322		writeJSON(stdout, report)
323		return 0
324	}
325	
326	// requireEOF 拒绝 JSON 文档之后的尾随内容。
327	func requireEOF(dec *json.Decoder, what string) error {
328		if tok, err := dec.Token(); err != io.EOF {
329			if err == nil {
330				return fmt.Errorf("%s: unexpected trailing content after JSON document (token %v)", what, tok)
331			}
332			return fmt.Errorf("%s: %v", what, err)
333		}
334		return nil
335	}
336	
337	func runDemo(stdout io.Writer) int {
338		intents := []payflow.Intent{
339			{ID: "pay-1", Account: "aa-1", Paymaster: "pm-1", Amount: 1500, Asset: "usdc", Nonce: 1, State: "pending"},
340			{ID: "pay-2", Account: "aa-1", Paymaster: "pm-1", Amount: 900, Asset: "usdc", Nonce: 2, State: "pending"},
341		}
342		spent := map[string]bool{}
343		var settlements []payflow.Settlement
344		for _, intent := range intents {
345			settlement := payflow.Execute(intent, 30, spent, 2000)
346			settlements = append(settlements, settlement)
347			fmt.Fprintf(stdout, "intent=%s status=%s charged=%d reason=%s\n", settlement.Intent, settlement.Status, settlement.Charged, settlement.Reason)
348		}
349		duplicate := payflow.Execute(intents[0], 30, spent, 2000)
350		fmt.Fprintf(stdout, "duplicate of %s status=%s reason=%s\n", duplicate.Intent, duplicate.Status, duplicate.Reason)
351		fmt.Fprintln(stdout, "reconciliation gaps:", payflow.Reconcile(intents, settlements))
352		return 0
353	}
