550	// failNth 在第 nth 次（1 起）持久化时失败，其余成功。
551	type failNth struct {
552		nth   int
553		calls int
554	}
555	
556	func (f *failNth) FailNextPersist() bool {
557		f.calls++
558		return f.calls == f.nth
559	}
