881	// 成功全额退款：charged（含手续费）退回原账户、原资产；原结算保持不变；
882	// query 按退款成功顺序返回可追溯原结算的记录。
883	func TestRefundFullAmountIncludingFee(t *testing.T) {
884		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1010}})
885		l := openOrFail(t, path)
886		res, _ := l.Submit(FeeBatch{FeeBps: 100, Intents: []PaymentIntent{
887			{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: i64p(1000), Nonce: 1, State: "pending"},
888		}})
889		if res.Results[0].Status != StatusSettled {
890			t.Fatalf("settle: %+v", res.Results[0])
891		}
892		if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
893			t.Fatalf("balance after settle=%d want 0", bal)
894		}
895	
896		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "cancel")}})
897		if err != nil {
898			t.Fatal(err)
899		}
900		got := rr.Results[0]
901		if got.Status != StatusRefundSuccess {
902			t.Fatalf("status=%s want refunded: %+v", got.Status, got)
903		}
904		if got.SettlementID != "p1" || got.Account != "aa" || got.Asset != "usdc" || got.Charged != 1010 {
905			t.Fatalf("refund result fields: %+v", got)
906		}
907		if got.Record == nil || got.Record.Fee != 10 || got.Record.Amount != 1000 ||
908			got.Record.AfterSeq != 1 || got.Record.Seq != 1 {
909			t.Fatalf("refund record: %+v", got.Record)
910		}
911		// 全额（含手续费）退回。
912		if bal, _ := l.Balance("aa", "usdc"); bal != 1010 {
913			t.Fatalf("balance after refund=%d want 1010", bal)
914		}
915	
916		snap, _ := l.Query()
917		// 原结算记录及其编号、顺序保持不变。
918		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p1" || snap.Settlements[0].Charged != 1010 {
919			t.Fatalf("original settlement altered: %+v", snap.Settlements)
920		}
921		if len(snap.Refunds) != 1 {
922			t.Fatalf("want 1 refund, got %+v", snap.Refunds)
923		}
924		rf := snap.Refunds[0]
925		if rf.ID != "r1" || rf.SettlementID != "p1" || rf.Reason != "cancel" ||
926			rf.Account != "aa" || rf.Asset != "usdc" || rf.Charged != 1010 {
927			t.Fatalf("query refund not traceable to settlement: %+v", rf)
928		}
929	}
