1025		if fail.Results[0].Status != StatusFunds {
1026			t.Fatalf("setup: %+v", fail.Results[0])
1027		}
1028		// pok 成功。
1029		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("pok", "aa", "usdc", 30)}}); err != nil {
1030			t.Fatal(err)
1031		}
1032	
1033		rr, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{
1034			refundReq("r-missing", "ghost", "x"),
1035			refundReq("r-failed", "pbad", "x"), // 原付款只曾失败
1036			refundReq("r-ok", "pok", "x"),
1037		}})
1038		if rr.Results[0].Status != StatusNotFound || rr.Results[1].Status != StatusNotFound {
1039			t.Fatalf("want not_found for missing/failed, got %+v", rr.Results)
1040		}
1041		if rr.Results[2].Status != StatusRefundSuccess {
1042			t.Fatalf("valid refund: %+v", rr.Results[2])
1043		}
1044		balAfter, _ := l.Balance("aa", "usdc") // 100-30+30 = 100
1045	
1046		// 新退款编号指向已退款结算：already_refunded，不加余额。
1047		rr2, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r-other", "pok", "again")}})
1048		if rr2.Results[0].Status != StatusAlreadyRefunded {
1049			t.Fatalf("want already_refunded, got %+v", rr2.Results[0])
1050		}
1051		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
1052			t.Fatalf("already_refunded changed balance: %d vs %d", bal, balAfter)
1053		}
1054		// not_found 的编号未被占用，可以换成存在的目标（p2）再成功。
1055		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p2", "aa", "usdc", 10)}}); err != nil {
1056			t.Fatal(err)
1057		}
1058		rr4, _ := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r-failed", "p2", "reused id")}})
1059		if rr4.Results[0].Status != StatusRefundSuccess {
1060			t.Fatalf("previously-not-found id should be reusable, got %+v", rr4.Results[0])
1061		}
