	}
	link := filepath.Join(root, "link")
	if err := os.Symlink(dir, link); err != nil {
		t.Skipf("symlink unsupported: %v", err)
	}
	linkPath = filepath.Join(link, "ledger.json")
	return realPath, linkPath
}

