	if err != nil {
		t.Fatal(err)
	}
	d := dup.Results[0]
	if d.Status != StatusDuplicate || d.Record == nil || d.Record.Seq != 1 || d.Record.Charged != 300 {
		t.Fatalf("cross-handle duplicate: %+v", d)
	}

